{"implementation":"def solve(case):
    threshold = case['threshold']
    calls = case['calls']
    accepted_ids = []
    diagnostics = []
    for call in calls:
        call_id = call['call_id']
        gain = call['loss_without_call'] - call['loss_with_call']
        normalized_gain = gain / call['prediction_tokens']
        accept = call['parseable'] and normalized_gain >= threshold
        if accept:
            accepted_ids.append(call_id)
        diagnostics.append({
            'accepted': accept,
            'call_id': call_id,
            'normalized_gain': normalized_gain
        })
    return {
        'accepted_call_ids': accepted_ids,
        'diagnostics': diagnostics
    }"}
